def word_pattern(pattern: str, s: str) -> bool:
    words = s.split()
    if len(words) != len(pattern):
        return False
    c2w, w2c = {}, {}
    for c, w in zip(pattern, words):
        if (c in c2w and c2w[c] != w) or (w in w2c and w2c[w] != c):
            return False
        c2w[c] = w
        w2c[w] = c
    return True

