def find_anagrams(s: str, p: str) -> list[int]:
    ns, np = len(s), len(p)
    if np > ns:
        return []
    p_cnt = [0] * 26
    w_cnt = [0] * 26
    for ch in p:
        p_cnt[ord(ch) - 97] += 1
    for i in range(np):
        w_cnt[ord(s[i]) - 97] += 1
    res = [0] if w_cnt == p_cnt else []
    for i in range(np, ns):
        w_cnt[ord(s[i]) - 97] += 1
        w_cnt[ord(s[i - np]) - 97] -= 1
        if w_cnt == p_cnt:
            res.append(i - np + 1)
    return res

