from itertools import zip_longest

def backspace_compare(s: str, t: str) -> bool:
    def gen(st: str):
        skip = 0
        for ch in reversed(st):
            if ch == '#':
                skip += 1
            elif skip > 0:
                skip -= 1
            else:
                yield ch
    return all(a == b for a, b in zip_longest(gen(s), gen(t)))

