from collections import deque

class TreeNode:
    def __init__(self, val=0):
        self.val = val; self.left = None; self.right = None

def _build(arr):
    if not arr or arr[0] is None:
        return None
    root = TreeNode(arr[0])
    dq = deque([root]); i = 1
    while dq and i < len(arr):
        node = dq.popleft()
        if i < len(arr) and arr[i] is not None:
            node.left = TreeNode(arr[i]); dq.append(node.left)
        i += 1
        if i < len(arr) and arr[i] is not None:
            node.right = TreeNode(arr[i]); dq.append(node.right)
        i += 1
    return root

def is_same_tree(p: list, q: list) -> bool:
    def same(a, b):
        if not a and not b:
            return True
        if not a or not b or a.val != b.val:
            return False
        return same(a.left, b.left) and same(a.right, b.right)
    return same(_build(p), _build(q))

