        return False
    root = TreeNode(tree[0])
    dq = deque([root]); i = 1
    while dq and i < len(tree):
        node = dq.popleft()
        if i < len(tree) and tree[i] is not None:
            node.left = TreeNode(tree[i]); dq.append(node.left)
        i += 1
        if i < len(tree) and tree[i] is not None:
            node.right = TreeNode(tree[i]); dq.append(node.right)
        i += 1
    def dfs(node, rem):
        if not node:
            return False
        if not node.left and not node.right:
            return rem == node.val
        return dfs(node.left, rem - node.val) or dfs(node.right, rem - node.val)
    return dfs(root, target_sum)

