class TreeNode:
    def __init__(self, val=0):
        self.val = val; self.left = None; self.right = None

def lca_binary_tree(tree: list, p: int, q: int) -> int:
    root = TreeNode(tree[0])
    dq = deque([root]); i = 1
    while dq and i < len(tree):
        node = dq.popleft()
        if i < len(tree) and tree[i] is not None:
            node.left = TreeNode(tree[i]); dq.append(node.left)
        i += 1
        if i < len(tree) and tree[i] is not None:
            node.right = TreeNode(tree[i]); dq.append(node.right)
        i += 1
    def dfs(node):
        if not node or node.val == p or node.val == q:
