def flood_fill(image: list[list[int]], sr: int, sc: int, color: int) -> list[list[int]]:
    orig = image[sr][sc]
    if orig == color:
        return image
    m, n = len(image), len(image[0])
    image[sr][sc] = color
    q = deque([(sr, sc)])
    while q:
        r, c = q.popleft()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < m and 0 <= nc < n and image[nr][nc] == orig:
                image[nr][nc] = color
                q.append((nr, nc))
    return image

