from collections import deque

def max_area_of_island(grid: list[list[int]]) -> int:
    m, n = len(grid), len(grid[0])
    g = [row[:] for row in grid]
    best = 0
    for r in range(m):
        for c in range(n):
            if g[r][c] == 1:
                g[r][c] = 0
                q = deque([(r, c)])
                area = 0
                while q:
                    cr, cc = q.popleft()
                    area += 1
                    for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < m and 0 <= nc < n and g[nr][nc] == 1:
                            g[nr][nc] = 0
                            q.append((nr, nc))
                if area > best:
                    best = area
