from collections import deque

def pacific_atlantic(heights: list[list[int]]) -> list[list[int]]:
    m, n = len(heights), len(heights[0])
    def bfs(starts):
        vis = set(starts)
        q = deque(starts)
        while q:
            r, c = q.popleft()
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < m and 0 <= nc < n and (nr, nc) not in vis and heights[nr][nc] >= heights[r][c]:
                    vis.add((nr, nc))
                    q.append((nr, nc))
        return vis
    pac = bfs([(0, c) for c in range(n)] + [(r, 0) for r in range(m)])
    atl = bfs([(m - 1, c) for c in range(n)] + [(r, n - 1) for r in range(m)])
    return sorted([r, c] for r, c in (pac & atl))

