  for (let index = head.length - 1; index >= 0; index--) {
    current = { value: head[index], next: current };
  }
  let previous = null;
  while (current) {
    const next = current.next;
    current.next = previous;
    previous = current;
    current = next;
  }
  const result = [];
  while (previous) {
    result.push(previous.value);
    previous = previous.next;
  }
  return result;
}

