from collections import deque

def rangeSumBST(root: list, low: int, high: int) -> int:
    if not root or root[0] is None:
        return 0
    class Node:
        def __init__(self, v): self.val, self.left, self.right = v, None, None
    head = Node(root[0])
    q = deque([head])
    i = 1
    while q and i < len(root):
        cur = q.popleft()
        if i < len(root) and root[i] is not None:
            cur.left = Node(root[i])
            q.append(cur.left)
        i += 1
        if i < len(root) and root[i] is not None:
            cur.right = Node(root[i])
            q.append(cur.right)
        i += 1
    total = 0
    stack = [head]
    while stack:
        node = stack.pop()
        if low <= node.val <= high:
            total += node.val
        if node.left and node.val > low:
            stack.append(node.left)
        if node.right and node.val < high:
            stack.append(node.right)
    return total

