def restoreIpAddresses(s: str) -> list[str]:
    n = len(s)
    if n < 4 or n > 12:
        return []
    res = []
    parts = []
    def dfs(idx: int) -> None:
        if len(parts) == 4:
            if idx == n:
                res.append('.'.join(parts))
            return
        rem_parts = 4 - len(parts)
        rem_chars = n - idx
        if rem_chars < rem_parts or rem_chars > rem_parts * 3:
            return
        for length in range(1, 4):
            if idx + length > n:
                break
            seg = s[idx:idx + length]
            if (length > 1 and seg[0] == '0') or int(seg) > 255:
                continue
            parts.append(seg)
            dfs(idx + length)
            parts.pop()
    dfs(0)
    return res

