import java.util.*;
class Solution {
    public int[][] incidentWindows(int[] readings, int limit) {
        List<int[]> windows = new ArrayList<>();
        for (int index = 0; index < readings.length; index++) {
            if (readings[index] <= limit) continue;
            int[] last = windows.isEmpty() ? null : windows.get(windows.size() - 1);
            if (last != null && index - last[1] <= 2) last[1] = index;
            else windows.add(new int[]{index, index});
        }
        return windows.toArray(new int[0][]);
    }
}

