def count_safe_gain_chains(gains: list[int], ceiling: int) -> int:
    if ceiling <= 1: return 0
    prod, l, ans = 1, 0, 0
    for r, g in enumerate(gains):
        prod *= g
        while prod >= ceiling:
            prod //= gains[l]; l += 1
        ans += r - l + 1
    return ans

