from collections import deque

class Node:
    def __init__(self, v): self.v = v; self.l = None; self.r = None

def kth_lowest_score(tree: list, k: int) -> int:
    root = Node(tree[0]); q = deque([root]); i = 1
    while q and i < len(tree):
        u = q.popleft()
        if i < len(tree) and tree[i] is not None: u.l = Node(tree[i]); q.append(u.l)
        i += 1
        if i < len(tree) and tree[i] is not None: u.r = Node(tree[i]); q.append(u.r)
        i += 1
    st, cur = [], root
    while cur or st:
        while cur: st.append(cur); cur = cur.l
        cur = st.pop(); k -= 1
        if k == 0: return cur.v
        cur = cur.r
    return -1

