from collections import deque

def can_build_all(num_pkgs: int, deps: list[list[int]]) -> bool:
    adj = [[] for _ in range(num_pkgs)]
    indeg = [0] * num_pkgs
    for a, b in deps:
        adj[b].append(a); indeg[a] += 1
    q = deque(i for i in range(num_pkgs) if indeg[i] == 0)
    built = 0
    while q:
        u = q.popleft(); built += 1
        for v in adj[u]:
            indeg[v] -= 1
            if indeg[v] == 0: q.append(v)
    return built == num_pkgs

