import heapq
from collections import defaultdict

def broadcast_convergence(links: list[list[int]], n: int, origin: int) -> int:
    adj = defaultdict(list)
    for u, v, w in links: adj[u].append((v, w))
    dist = {origin: 0}
    h = [(0, origin)]
    while h:
        d, u = heapq.heappop(h)
        if d > dist[u]: continue
        for v, w in adj[u]:
            nd = d + w
            if nd < dist.get(v, float('inf')):
                dist[v] = nd; heapq.heappush(h, (nd, v))
    return max(dist.values()) if len(dist) == n else -1

