def countRangeSum(nums: list[int], lower: int, upper: int) -> int:
    pref = [0]
    for x in nums:
        pref.append(pref[-1] + x)
    def sort_count(l: int, r: int) -> int:
        if r - l <= 1:
            return 0
        m = (l + r) // 2
        cnt = sort_count(l, m) + sort_count(m, r)
        lo = hi = m
        for x in pref[l:m]:
            while lo < r and pref[lo] - x < lower:
                lo += 1
            while hi < r and pref[hi] - x <= upper:
                hi += 1
            cnt += hi - lo
        pref[l:r] = sorted(pref[l:r])
        return cnt
    return sort_count(0, len(pref))

