def minWindowSubsequence(s1: str, s2: str) -> str:
    n, m = len(s1), len(s2)
    dp = [-1] * (m + 1)
    best_len = n + 1
    best_start = -1
    for i, ch in enumerate(s1):
        for j in range(m, 0, -1):
            if ch == s2[j - 1]:
                dp[j] = i if j == 1 else dp[j - 1]
        if dp[m] != -1:
            cur_len = i - dp[m] + 1
            if cur_len < best_len:
                best_len = cur_len
                best_start = dp[m]
    return '' if best_start == -1 else s1[best_start:best_start + best_len]

