def cherryPickup(grid: list[list[int]]) -> int:
    R, C = len(grid), len(grid[0])
    dp = [[0] * C for _ in range(C)]
    for c1 in range(C):
        for c2 in range(C):
            dp[c1][c2] = grid[R - 1][c1] + (grid[R - 1][c2] if c1 != c2 else 0)
    for r in range(R - 2, -1, -1):
        ndp = [[0] * C for _ in range(C)]
        for c1 in range(C):
            for c2 in range(C):
                best = 0
                for nc1 in (c1 - 1, c1, c1 + 1):
                    if 0 <= nc1 < C:
                        for nc2 in (c2 - 1, c2, c2 + 1):
                            if 0 <= nc2 < C and dp[nc1][nc2] > best:
                                best = dp[nc1][nc2]
                val = grid[r][c1] + (grid[r][c2] if c1 != c2 else 0)
                ndp[c1][c2] = val + best
        dp = ndp
    return dp[0][C - 1]

