        u = q.popleft()
        if i < len(tree) and tree[i] is not None: u.l = Node(tree[i]); q.append(u.l)
        i += 1
        if i < len(tree) and tree[i] is not None: u.r = Node(tree[i]); q.append(u.r)
        i += 1
    best = float('-inf')
    def gain(u):
        nonlocal best
        if not u: return 0
        lg, rg = max(0, gain(u.l)), max(0, gain(u.r))
        best = max(best, u.v + lg + rg)
        return u.v + max(lg, rg)
    gain(root)
    return best

