from collections import deque

class Node:
    def __init__(self, v): self.v = v; self.l = None; self.r = None

def mirror_org_chart(chart: list) -> list:
    if not chart or chart[0] is None: return []
    root = Node(chart[0]); q = deque([root]); i = 1
    while q and i < len(chart):
        u = q.popleft()
        if i < len(chart) and chart[i] is not None: u.l = Node(chart[i]); q.append(u.l)
        i += 1
        if i < len(chart) and chart[i] is not None: u.r = Node(chart[i]); q.append(u.r)
        i += 1
    def flip(u):
        if not u: return None
        u.l, u.r = flip(u.r), flip(u.l)
        return u
    root = flip(root)
    res, q = [], deque([root])
    while q:
        u = q.popleft()
        if u: res.append(u.v); q.append(u.l); q.append(u.r)
        else: res.append(None)
    while res and res[-1] is None: res.pop()
    return res

