def cheapest_charter(n: int, legs: list[list[int]], src: int, dst: int, max_layovers: int) -> int:
    INF = float('inf')
    dist = [INF] * n; dist[src] = 0
    for _ in range(max_layovers + 1):
        nxt = dist[:]
        for u, v, w in legs:
            if dist[u] != INF and dist[u] + w < nxt[v]:
                nxt[v] = dist[u] + w
        dist = nxt
    return -1 if dist[dst] == INF else dist[dst]

