def count_scanner_layouts(n: int) -> int:
    full = (1 << n) - 1
    def bt(r, cols, d1, d2):
        if r == n: return 1
        cnt = 0
        avail = full & ~(cols | d1 | d2)
        while avail:
            bit = avail & -avail
            avail ^= bit
            cnt += bt(r + 1, cols | bit, (d1 | bit) << 1, (d2 | bit) >> 1)
        return cnt
    return bt(0, 0, 0, 0)

