def eval_formula(formula: list[str]) -> int:
    st = []
    for tok in formula:
        if tok in ('+', '-', '*', '/'):
            b, a = st.pop(), st.pop()
            if tok == '+': st.append(a + b)
            elif tok == '-': st.append(a - b)
            elif tok == '*': st.append(a * b)
            else: st.append((-1 if (a < 0) != (b < 0) else 1) * (abs(a) // abs(b)))
        else:
            st.append(int(tok))
    return st[0]

