def partition_qos_tiers(tiers: list[int]) -> list[int]:
    lo = mid = 0
    hi = len(tiers) - 1
    while mid <= hi:
        if tiers[mid] == 0:
            tiers[lo], tiers[mid] = tiers[mid], tiers[lo]
            lo += 1; mid += 1
        elif tiers[mid] == 1:
            mid += 1
        else:
            tiers[mid], tiers[hi] = tiers[hi], tiers[mid]
            hi -= 1
    return tiers

