def shared_backbone_len(strand_a: str, strand_b: str) -> int:
    n = len(strand_b)
    prev = [0] * (n + 1)
    for a in strand_a:
        curr = [0] * (n + 1)
        for j, b in enumerate(strand_b):
            curr[j + 1] = prev[j] + 1 if a == b else max(prev[j + 1], curr[j])
        prev = curr
    return prev[n]
